SELECT *
FROM acc_acceptance_scope_binding
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND project_stage_snapshot_id = #{query.projectStageSnapshotId}
  AND delivery_scope_id = #{query.deliveryScopeId}
  AND scope_allocation_version = #{query.scopeAllocationVersion}
  AND deleted = b'0'
FOR UPDATE
